/** Writes src/lib/units-index.ts: one import per data/units/*.json, in course order (by id). */
import { readdirSync, writeFileSync } from "node:fs";

const ids = readdirSync(new URL("../data/units/", import.meta.url))
  .filter((file) => file.endsWith(".json"))
  .map((file) => file.replace(".json", ""))
  .sort();
const name = (id: string) => `u${id.replaceAll("-", "_")}`;
writeFileSync(
  new URL("../src/lib/units-index.ts", import.meta.url),
  [
    "// Generated by `pnpm units:index` from data/units/*.json, in course order. Do not edit.",
    'import type { Unit } from "./units";',
    ...ids.map((id) => `import ${name(id)} from "../../data/units/${id}.json";`),
    "",
    `export const UNITS = [${ids.map(name).join(", ")}] as Unit[];`,
    "",
  ].join("\n"),
);
console.log(`${ids.length} units`);
